window.AP_BIOLOGY_DECKS = [{"id":"apbio-unit-1","name":"AP Biology · Unit 1","shortName":"Unit 1: Chemistry of Life","builtIn":true,"sourceTitle":"AP Biology Course and Exam Description, Effective Fall 2025; EBSCO AP Biology Study Guide","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf","cards":[{"id":"apbio-unit-1-c1","front":"polar covalent bond","back":"A covalent bond between atoms that differ in electronegativity."},{"id":"apbio-unit-1-c2","front":"electronegativity","back":"The attraction of a given atom for the electrons of a covalent bond."},{"id":"apbio-unit-1-c3","front":"van der Waals interactions","back":"Weak attractions between molecules or parts of molecules that result from transient local partial charges."},{"id":"apbio-unit-1-c4","front":"cohesion","back":"The linking together of like molecules, often by hydrogen bonds."},{"id":"apbio-unit-1-c5","front":"specific heat","back":"The amount of heat that must be absorbed or lost for 1 g of a substance to change its temperature by 1°C."},{"id":"apbio-unit-1-c6","front":"buffer","back":"A solution that contains a weak acid and its corresponding base."},{"id":"apbio-unit-1-c7","front":"hydrophilic","back":"Having an affinity for water."},{"id":"apbio-unit-1-c8","front":"hydrophobic","back":"Having no affinity for water; tending to coalesce and form droplets in water."},{"id":"apbio-unit-1-c9","front":"aqueous solution","back":"A solution in which water is the solvent."},{"id":"apbio-unit-1-c10","front":"monomer","back":"The subunit that serves as the building block of a polymer."},{"id":"apbio-unit-1-c11","front":"hydrolysis","back":"A chemical reaction that breaks bonds between two molecules by the addition of water; functions in disassembly of polymers to monomers."},{"id":"apbio-unit-1-c12","front":"carbohydrate","back":"A sugar (monosaccharide) or one of its dimers (disaccharides) or polymers (polysaccharides)."},{"id":"apbio-unit-1-c13","front":"monosaccharide","back":"The simplest carbohydrate, active alone or serving as a monomer for disaccharides and polysaccharides."},{"id":"apbio-unit-1-c14","front":"cellulose","back":"A structural polysaccharide of plant cell walls, consisting of glucose monomers joined by b glycosidic linkages."},{"id":"apbio-unit-1-c15","front":"glycogen","back":"An extensively branched glucose storage polysaccharide found in the liver and muscle of animals; the animal equiv alent of starch."},{"id":"apbio-unit-1-c16","front":"lipid","back":"Any of a group of large biological molecules, including fats, phospholipids, and steroids, that mix poorly, if at all, with water."},{"id":"apbio-unit-1-c17","front":"fatty acid","back":"A carboxylic acid with a long carbon chain."},{"id":"apbio-unit-1-c18","front":"phospholipid","back":"A lipid made up of glycerol joined to two fatty acids and a phosphate group."},{"id":"apbio-unit-1-c19","front":"amino acid","back":"An organic molecule possessing both a carboxyl and an amino group."},{"id":"apbio-unit-1-c20","front":"protein","back":"A biologically functional molecule consisting of one or more polypeps tides folded and coiled into a specific threedimensional structure."},{"id":"apbio-unit-1-c21","front":"denaturation","back":"In proteins, a process in which a protein loses its native shape due to the disruption of weak chemical bonds and interactions, thereby becoming biologically inactive; in DNA, the separation of the two strands of the double helix."},{"id":"apbio-unit-1-c22","front":"nucleic acid","back":"A polymer (polynucleotide) consisting of many nucleotide monomers; serves as a blueprint for protein and, through the actions of proteins, for all cellular activities."},{"id":"apbio-unit-1-c23","front":"nucleotide","back":"The building block of a nucleic acid, consisting of a five-carbon sugar covalently bonded to a nitrogenous base y."},{"id":"apbio-unit-1-c24","front":"ATP (adenosine triphosphate)","back":"An adenine-containing nucleoside triphosphate that releases free energy when its phosphate bonds are hydrolyzed."},{"id":"apbio-unit-1-c25","front":"Hydrogen bond","back":"A weak attraction between a partially positive hydrogen atom and an electronegative atom; collectively, these bonds give water many of its biological properties."},{"id":"apbio-unit-1-c26","front":"Adhesion","back":"The attraction between unlike substances, such as water molecules and the walls of plant xylem."},{"id":"apbio-unit-1-c27","front":"Surface tension","back":"Resistance of a liquid surface to stretching or breaking because cohesive forces pull surface molecules inward."},{"id":"apbio-unit-1-c28","front":"pH","back":"A logarithmic measure of hydrogen ion concentration; each one-unit change represents a tenfold change in H+ concentration."},{"id":"apbio-unit-1-c29","front":"Dehydration synthesis","back":"A reaction that covalently joins monomers while releasing a molecule of water."},{"id":"apbio-unit-1-c30","front":"Polymer","back":"A large molecule made of repeating or similar monomer subunits."},{"id":"apbio-unit-1-c31","front":"Peptide bond","back":"The covalent bond formed between the carboxyl group of one amino acid and the amino group of another."},{"id":"apbio-unit-1-c32","front":"Primary protein structure","back":"The unique amino acid sequence of a polypeptide."},{"id":"apbio-unit-1-c33","front":"Secondary protein structure","back":"Local alpha helices and beta sheets formed mainly by hydrogen bonding along the polypeptide backbone."},{"id":"apbio-unit-1-c34","front":"Tertiary protein structure","back":"The overall three-dimensional shape of one polypeptide produced by interactions among its side chains."},{"id":"apbio-unit-1-c35","front":"Quaternary protein structure","back":"The arrangement of two or more polypeptide subunits into one functional protein."},{"id":"apbio-unit-1-c36","front":"Triglyceride","back":"A lipid consisting of glycerol joined to three fatty acids; it functions mainly in long-term energy storage."},{"id":"apbio-unit-1-c37","front":"Functional group","back":"A specific group of atoms that gives an organic molecule characteristic chemical properties."},{"id":"apbio-unit-1-c38","front":"Hydroxyl group","back":"A polar -OH functional group found in alcohols that can form hydrogen bonds with water."},{"id":"apbio-unit-1-c39","front":"Carboxyl group","back":"An acidic -COOH functional group that can donate H+ and become negatively charged."},{"id":"apbio-unit-1-c40","front":"Saturated fatty acid","back":"A fatty acid with no carbon-carbon double bonds; its straight chain packs tightly."},{"id":"apbio-unit-1-c41","front":"Unsaturated fatty acid","back":"A fatty acid with one or more carbon-carbon double bonds that introduce bends and reduce tight packing."},{"id":"apbio-unit-1-c42","front":"Molecular directionality","back":"The chemically distinct ends of a biological polymer, such as the 5' and 3' ends of nucleic acids or the amino and carboxyl ends of proteins."}],"questions":[],"feynmanPrompts":[{"id":"apbio-unit-1-f1","prompt":"Water's properties and biological systems"},{"id":"apbio-unit-1-f2","prompt":"Structure and function of biological macromolecules"}]},{"id":"apbio-unit-2","name":"AP Biology · Unit 2","shortName":"Unit 2: Cells","builtIn":true,"sourceTitle":"AP Biology Course and Exam Description, Effective Fall 2025; EBSCO AP Biology Study Guide","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf","cards":[{"id":"apbio-unit-2-c1","front":"cell","back":"Life’s fundamental unit of structure and function; the smallest unit of organization that can perform all activities required for life."},{"id":"apbio-unit-2-c2","front":"prokaryotic cell","back":"A type of m cell lacking a membrane-enclosed nucleus and membrane-enclosed organelles."},{"id":"apbio-unit-2-c3","front":"nucleus","back":"An atom’s central core, containing d protons and neutrons."},{"id":"apbio-unit-2-c4","front":"nuclear envelope","back":"In a eukaryotic cell, the double membrane that surrounds the nucleus perforated with pores that regulate traffic with the cytoplasm."},{"id":"apbio-unit-2-c5","front":"ribosome","back":"A complex of rRNA and oprotein molecules that functions as a site of protein synthesis in the cytoplasm; consists of a large and a small subunit."},{"id":"apbio-unit-2-c6","front":"endomembrane system","back":"The collection of membranes inside and surrounding a eukaryotic cell, related either through direct physical contact or by the transfer of membranous vesicles; includes the plasma membrane, the nuclear envelope, the smooth and rough endoplasmic reticulum, the Golgi apparatus, lysosomes, vesicles, and vacuoles."},{"id":"apbio-unit-2-c7","front":"endoplasmic reticulum (ER)","back":"An extensive membranous network in eukaryotic cells, continuous with the outer nuclear membrane and composed of ribosome-studded (rough) and ribosome-free (smooth) regions."},{"id":"apbio-unit-2-c8","front":"rough ER","back":"That portion of the endoplasmic reticulum with ribosomes attached."},{"id":"apbio-unit-2-c9","front":"smooth ER","back":"That portion of the endoplasmic reticulum that is free of ribosomes."},{"id":"apbio-unit-2-c10","front":"Golgi apparatus","back":"An organelle in teukaryotic cells consisting of stacks of flat e membranous sacs that modify, store, and e."},{"id":"apbio-unit-2-c11","front":"lysosome","back":"A membrane-enclosed sac of hydrolytic enzymes found in the cytoplasm of animal cells and some protists."},{"id":"apbio-unit-2-c12","front":"mitochondria","back":") An organelle in eukaryotic cells that serves as the site of cellular respiration; uses oxygen to break down organic molecules and synthesize ATP."},{"id":"apbio-unit-2-c13","front":"cytoskeleton","back":"A network of microtubules, microfilaments, and intermediate filaments that extend throughout the cytoplasm and serve a variety of mechanical, transport, and signaling functions."},{"id":"apbio-unit-2-c14","front":"microtubule","back":"A hollow rod composed of tubulin proteins that makes up part of the cytoskeleton in all eukaryotic cells and is found in cilia n and flagella."},{"id":"apbio-unit-2-c15","front":"microfilament","back":"A cable composed of actin proteins in the cytoplasm of almost every eukaryotic cell, making up part of the cytoskeleton and acting alone or with myosin to cause cell contraction; also called an actin filament."},{"id":"apbio-unit-2-c16","front":"plasma membrane","back":"The membrane at the boundary of every cell that acts as a selective barrier, regulating the cell’s chemical composition."},{"id":"apbio-unit-2-c17","front":"fluid mosaic model","back":"The currently accepted model of cell membrane structure, which envisions the membrane as a mosaic of protein molecules drifting laterally in a fluid bilayer of phospholipids."},{"id":"apbio-unit-2-c18","front":"amphipathic","back":"Having both a hydrophilic region and a hydrophobic region."},{"id":"apbio-unit-2-c19","front":"diffusion","back":"The random thermal motion of particles of liquids, gases, or solids."},{"id":"apbio-unit-2-c20","front":"osmosis","back":"The diffusion of free water across a selectively permeable membrane."},{"id":"apbio-unit-2-c21","front":"facilitated diffusion","back":"The passage of molecules or ions down their electrochemical gradient across a biological membrane with the assistance of specific transmembrane transport proteins, requiring no energy - expenditure.."},{"id":"apbio-unit-2-c22","front":"active transport","back":"The movement of a substance across a cell membrane against its concentration or electrochemical gradient, mediated by specific transport proteins and requiring an expenditure of energy."},{"id":"apbio-unit-2-c23","front":"electrochemical gradient","back":"The diffusion es gradient of an ion, which is affected by both the concentration difference of an ion across n a membrane (a chemical force) and the ion’s tendency to move relative to the membrane potential (an electrical force)."},{"id":"apbio-unit-2-c24","front":"endocytosis","back":"Cellular uptake of biological molecules and particulate matter via formation of vesicles from the plasma membrane."},{"id":"apbio-unit-2-c25","front":"exocytosis","back":"The cellular secretion of biological molecules by the fusion of vesicles containing them with the plasma membrane."},{"id":"apbio-unit-2-c26","front":"Eukaryotic cell","back":"A cell containing a membrane-bound nucleus and other membrane-bound organelles."},{"id":"apbio-unit-2-c27","front":"Chloroplast","back":"The photosynthetic organelle of plants and algae; its thylakoid membranes capture light energy and its stroma contains the Calvin cycle."},{"id":"apbio-unit-2-c28","front":"Selective permeability","back":"The property of a membrane that permits some substances to cross more readily than others."},{"id":"apbio-unit-2-c29","front":"Surface-area-to-volume ratio","back":"The amount of membrane surface relative to cell volume; it decreases as a cell grows and limits exchange with the environment."},{"id":"apbio-unit-2-c30","front":"Tonicity","back":"A solution's ability to cause a cell to gain or lose water, determined by nonpenetrating solute concentrations."},{"id":"apbio-unit-2-c31","front":"Water potential","back":"The potential energy of water relative to pure water; water moves from higher water potential to lower water potential."},{"id":"apbio-unit-2-c32","front":"Aquaporin","back":"A membrane channel protein that enables rapid, selective movement of water across a membrane."},{"id":"apbio-unit-2-c33","front":"Sodium-potassium pump","back":"An ATP-powered transport protein that moves three Na+ out of a cell and two K+ into it per cycle."},{"id":"apbio-unit-2-c34","front":"Endosymbiotic theory","back":"The hypothesis that mitochondria and chloroplasts originated as free-living prokaryotes engulfed by an ancestral cell."},{"id":"apbio-unit-2-c35","front":"Compartmentalization","back":"Division of a cell into regions that maintain distinct conditions and allow incompatible reactions to occur efficiently."},{"id":"apbio-unit-2-c36","front":"Plasmolysis","back":"Separation of a plant cell's plasma membrane from its wall after water leaves the cell in a hypertonic environment."},{"id":"apbio-unit-2-c37","front":"Cotransport","back":"Coupled transport in which movement of one solute down its electrochemical gradient powers movement of another solute."},{"id":"apbio-unit-2-c38","front":"Membrane protein","back":"A protein associated with a membrane that may transport substances, receive signals, catalyze reactions, identify cells, or attach structures."},{"id":"apbio-unit-2-c39","front":"Water-potential equation","back":"Water potential is calculated as Ψ = Ψs + Ψp, the sum of solute potential and pressure potential."},{"id":"apbio-unit-2-c40","front":"Solute-potential equation","back":"For a solution, Ψs = -iCRT, where i is the ionization constant, C is molar concentration, R is the pressure constant, and T is absolute temperature."},{"id":"apbio-unit-2-c41","front":"Evidence for endosymbiosis","back":"Mitochondria and chloroplasts contain circular DNA, bacterial-like ribosomes, double membranes, and divide independently by binary fission."}],"questions":[],"feynmanPrompts":[{"id":"apbio-unit-2-f1","prompt":"Cell structure and function"},{"id":"apbio-unit-2-f2","prompt":"Membrane transport and osmoregulation"},{"id":"apbio-unit-2-f3","prompt":"Origins of cellular compartmentalization"}]},{"id":"apbio-unit-3","name":"AP Biology · Unit 3","shortName":"Unit 3: Cellular Energetics","builtIn":true,"sourceTitle":"AP Biology Course and Exam Description, Effective Fall 2025; EBSCO AP Biology Study Guide","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf","cards":[{"id":"apbio-unit-3-c1","front":"enzyme","back":"A macromolecule serving as a catalyst, a chemical agent that increases the rate of a reaction without being consumed by the reaction."},{"id":"apbio-unit-3-c2","front":"activation energy","back":"The amount of energy that reactants must absorb before a chemical reaction will start; also called free energy of activation."},{"id":"apbio-unit-3-c3","front":"active site","back":"The specific region of an enzyme that binds the substrate and that forms the pocket in which catalysis occurs."},{"id":"apbio-unit-3-c4","front":"substrate","back":"The reactant on which an enzyme works."},{"id":"apbio-unit-3-c5","front":"induced fit","back":"Caused by entry of the substrate, the change in shape of the active site of an enzyme so that it binds more snugly to the substrate."},{"id":"apbio-unit-3-c6","front":"competitive inhibitor","back":"A substance that reduces the activity of an enzyme by entering the active site in place of the substrate, whose structure it mimics."},{"id":"apbio-unit-3-c7","front":"noncompetitive inhibitor","back":"A substance that reduces the activity of an enzyme by binding to a location remote from the active site, changing the enzyme’s shape so that the active site no longer effectively catalyzes the conversion of substrate to product."},{"id":"apbio-unit-3-c8","front":"allosteric regulation","back":"The binding of a regulatory molecule to a protein at one site that affects the function of the protein at a different site."},{"id":"apbio-unit-3-c9","front":"feedback inhibition","back":"A method of metabolic control in which the end product of a metabolic pathway acts as an inhibitor of an enzyme within that pathway."},{"id":"apbio-unit-3-c10","front":"energy coupling","back":"In cellular metabolism, the use of energy released from an exergonic reaction to drive an endergonic reaction."},{"id":"apbio-unit-3-c11","front":"ATP synthase","back":"A complex of several membrane proteins that functions in chemiosmosis with adjacent electron transport chains, using the energy of a hydrogen ion (proton) concentration gradient to make ATP."},{"id":"apbio-unit-3-c12","front":"photosynthesis","back":"The conversion of light energy to chemical energy that is stored in sugars or other organic compounds; occurs in plants, algae, and certain prokaryotes."},{"id":"apbio-unit-3-c13","front":"photosystem","back":"A light-capturing unit located in the thylakoid membrane of the chloroplast or in the membrane of some prokaryotes, consisting of a reaction-center complex surrounded by numerous light-harvesting complexes."},{"id":"apbio-unit-3-c14","front":"light reactions","back":"The first of two major stages in photosynthesis (preceding the Calvin cycle)."},{"id":"apbio-unit-3-c15","front":"Calvin cycle","back":"The second of two major stages in photosynthesis (following the light reactions), involving fixation of atmospheric CO and reduction of the fixed carbon into 2 carbohydrate."},{"id":"apbio-unit-3-c16","front":"carbon fixation","back":"The initial incorporation of carbon from CO into an organic compound 2 by an autotrophic organism (a plant, another photosynthetic organism, or a chemoautotrophic prokaryote)."},{"id":"apbio-unit-3-c17","front":"rubisco","back":"Ribulose bisphosphate (RuBP) carboxylase-oxygenase, the enzyme that normally catalyzes the first step of the Calvin cycle (the addition of CO to RuBP)."},{"id":"apbio-unit-3-c18","front":"photorespiration","back":"A metabolic pathway that consumes oxygen and ATP, releases carbon dioxide, and decreases photosynthetic output."},{"id":"apbio-unit-3-c19","front":"cellular respiration","back":"The catabolic pathways of aerobic and anaerobic respiration, which break down organic molecules and use an electron transport chain for the production of ATP."},{"id":"apbio-unit-3-c20","front":"glycolysis","back":"A series of reactions that ultimately splits glucose into pyruvate."},{"id":"apbio-unit-3-c21","front":"acetyl CoA","back":"Acetyl coenzyme A; the entry compound for the citric acid cycle in cellular respiration, formed from a two-carbon fragment of pyruvate attached to a coenzyme."},{"id":"apbio-unit-3-c22","front":"electron transport chain","back":"A sequence of electron carrier molecules (membrane proe teins) that shuttle electrons down a series of r redox reactions that release energy used to make ATP."},{"id":"apbio-unit-3-c23","front":"proton-motive force","back":"The potential energy stored in the form of a proton electrochemical gradient, generated by the pumping of hydrogen ions (H +) across a biological membrane during chemiosmosis."},{"id":"apbio-unit-3-c24","front":"fermentation","back":"A catabolic process that makes a limited amount of ATP from glucose (or other sorganic molecules) without an electron transport chain and that produces a characteristic s end product, such as ethyl alcohol or lactic acid."},{"id":"apbio-unit-3-c25","front":"Oxidation-reduction reaction","back":"A reaction involving electron transfer; oxidation loses electrons and reduction gains electrons."},{"id":"apbio-unit-3-c26","front":"NADH","back":"A reduced electron carrier that delivers high-energy electrons to the electron transport chain."},{"id":"apbio-unit-3-c27","front":"FADH2","back":"A reduced electron carrier that donates electrons to the electron transport chain at a later point than NADH."},{"id":"apbio-unit-3-c28","front":"Citric acid cycle","back":"A cyclic pathway in the mitochondrial matrix that oxidizes acetyl-CoA, releases CO2, and produces NADH, FADH2, and ATP."},{"id":"apbio-unit-3-c29","front":"Oxidative phosphorylation","back":"ATP production powered by electron transport and chemiosmosis across a membrane."},{"id":"apbio-unit-3-c30","front":"Chemiosmosis","back":"Use of energy stored in a proton gradient to drive ATP synthesis through ATP synthase."},{"id":"apbio-unit-3-c31","front":"Cyclic electron flow","back":"A photosynthetic route around photosystem I that produces ATP without producing NADPH or oxygen."},{"id":"apbio-unit-3-c32","front":"C3 plant","back":"A plant that initially fixes CO2 into a three-carbon compound directly through the Calvin cycle."},{"id":"apbio-unit-3-c33","front":"C4 plant","back":"A plant that spatially separates initial CO2 fixation from the Calvin cycle, reducing photorespiration in hot conditions."},{"id":"apbio-unit-3-c34","front":"CAM plant","back":"A plant that opens stomata at night and temporally separates CO2 fixation from the Calvin cycle to conserve water."},{"id":"apbio-unit-3-c35","front":"Enzyme denaturation","back":"Loss of enzyme shape and function when environmental conditions disrupt the interactions maintaining protein structure."},{"id":"apbio-unit-3-c36","front":"Optimal temperature","back":"The temperature at which an enzyme's reaction rate is highest before instability or denaturation reduces activity."},{"id":"apbio-unit-3-c37","front":"Optimal pH","back":"The pH at which an enzyme's active-site chemistry and structure support its highest activity."},{"id":"apbio-unit-3-c38","front":"Reaction-rate graph","back":"A graph showing product formation or substrate loss over time; its slope represents reaction rate."},{"id":"apbio-unit-3-c39","front":"NADP+","back":"An oxidized electron carrier that accepts electrons and H+ during the light reactions of photosynthesis."},{"id":"apbio-unit-3-c40","front":"NADPH","back":"A reduced electron carrier produced in the light reactions and used to reduce carbon compounds in the Calvin cycle."},{"id":"apbio-unit-3-c41","front":"Anaerobic pathway","back":"An energy pathway that does not require oxygen; fermentation regenerates NAD+ so glycolysis can continue."}],"questions":[],"feynmanPrompts":[{"id":"apbio-unit-3-f1","prompt":"Enzyme function and regulation"},{"id":"apbio-unit-3-f2","prompt":"Photosynthesis"},{"id":"apbio-unit-3-f3","prompt":"Cellular respiration"}]},{"id":"apbio-unit-4","name":"AP Biology · Unit 4","shortName":"Unit 4: Cell Communication and Cell Cycle","builtIn":true,"sourceTitle":"AP Biology Course and Exam Description, Effective Fall 2025; EBSCO AP Biology Study Guide","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf","cards":[{"id":"apbio-unit-4-c1","front":"signal transduction","back":"The linkage of a mechan cal, chemical, or electromagnetic stimulus to specific cellular response."},{"id":"apbio-unit-4-c2","front":"signal transduction pathway","back":"A series of steps linking a mechanical, chemical, or electrical stimulus to a specific cellular response."},{"id":"apbio-unit-4-c3","front":"G protein","back":"A GTP-binding protein that relays signals from a plasma membrane signal recepd tor, known as a G protein-coupled receptor, to other signal transduction proteins inside the cell."},{"id":"apbio-unit-4-c4","front":"protein kinase","back":"An enzyme that transfers phosphate groups from ATP to a protein, thus phosphorylating the protein."},{"id":"apbio-unit-4-c5","front":"cyclic AMP (cAMP)","back":"Cyclic adenosine monophosphate, named because of its ring structure, is a common chemical signal that has a diversity of roles, including as a second messenger in many eukaryotic cells, and as a regulator of some bacterial operons."},{"id":"apbio-unit-4-c6","front":"phosphorylation cascade","back":"A series of chemical reactions during cell signaling mediated by enzymes (kinases), in which each kinase in turn phosphorylates and activates another, ultimately leading to phosphorylation of many proteins."},{"id":"apbio-unit-4-c7","front":"apoptosis","back":"A type of programme cell death, which is brought about by activation of enzymes that break down many chem ical components in the cell."},{"id":"apbio-unit-4-c8","front":"cell cycle","back":"An ordered sequence of events in the life of a cell, from its origin in the division of a parent cell until its own division into two."},{"id":"apbio-unit-4-c9","front":"cell cycle control system","back":"A cyclically operating set of molecules in the eukaryotic cell that both triggers and coordinates key events in the cell cycle."},{"id":"apbio-unit-4-c10","front":"cell division","back":"The reproduction of cells."},{"id":"apbio-unit-4-c11","front":"mitosis","back":"A process of nuclear division in eukaryotic cells conventionally divided into five stages: prophase, prometaphase, metaphase, anaphase, and telophase."},{"id":"apbio-unit-4-c12","front":"mitotic (M) phase","back":"The phase of the cell cycle that includes mitosis and cytokinesis."},{"id":"apbio-unit-4-c13","front":"S phase","back":"The synthesis phase of the cell cycle; the portion of interphase during which DNA is replicated."},{"id":"apbio-unit-4-c14","front":"prophase","back":"The first stage of mitosis, in which - the chromatin condenses into discrete chromosomes visible with a light microscope, the mitotic spindle begins to form, and the c nucleolus disappears but the nucleus remains intact."},{"id":"apbio-unit-4-c15","front":"prometaphase","back":"The second stage of mitosis, in which the nuclear envelope fragments and the spindle microtubules attach to the kinetochores of the chromosomes."},{"id":"apbio-unit-4-c16","front":"metaphase","back":"The third stage of mitosis, in which the spindle is complete and the chromosomes, attached to microtubules at their kinetochores, are all aligned at the metaphase plate."},{"id":"apbio-unit-4-c17","front":"metaphase plate","back":"An imaginary structure located at a plane midway between the two poles of a cell in metaphase on which the cen tromeres of all the duplicated chromosomes are located."},{"id":"apbio-unit-4-c18","front":"mitotic spindle","back":"An assemblage of microtubules and associated proteins that is involved in the movement of chromosomes during mitosis."},{"id":"apbio-unit-4-c19","front":"sister chromatids","back":"Two copies of a duplicated chromosome attached to each other by protein at the centromere and, sometimes, along the arms."},{"id":"apbio-unit-4-c20","front":"telophase","back":"The fifth and final stage of mitosis, in which daughter nuclei are forming and cytokinesis has typically begun."},{"id":"apbio-unit-4-c21","front":"cytokinesis","back":"The division of the cytoplasm to form two separate daughter cells immediately after mitosis, meiosis I, or meiosis II."},{"id":"apbio-unit-4-c22","front":"cleavage furrow","back":"The first sign of cleavage in an animal cell; a shallow groove around the cell in the cell surface near the old metaphase plate."},{"id":"apbio-unit-4-c23","front":"cell plate","back":"A membrane-bounded, flattened sac located at the midline of a dividing plant cell, inside which the new cell wall forms during cytokinesis."},{"id":"apbio-unit-4-c24","front":"cyclin","back":"A cellular protein that occurs in a cyclically fluctuating concentration and that plays an important role in regulating the cell cycle."},{"id":"apbio-unit-4-c25","front":"Ligand","back":"A signaling molecule that binds specifically to a receptor."},{"id":"apbio-unit-4-c26","front":"Receptor","back":"A protein that detects a signaling molecule and initiates a cellular response."},{"id":"apbio-unit-4-c27","front":"Second messenger","back":"A small intracellular molecule or ion, such as cAMP or Ca2+, that relays and amplifies a signal."},{"id":"apbio-unit-4-c28","front":"Calcium signaling","back":"Use of changes in cytosolic Ca2+ concentration as an intracellular signal."},{"id":"apbio-unit-4-c29","front":"Protein phosphatase","back":"An enzyme that removes phosphate groups from proteins, often reversing protein-kinase activity."},{"id":"apbio-unit-4-c30","front":"Negative feedback","back":"A regulatory mechanism in which a response reduces the original stimulus and stabilizes a system."},{"id":"apbio-unit-4-c31","front":"Positive feedback","back":"A regulatory mechanism in which a response amplifies the original stimulus until a terminating event occurs."},{"id":"apbio-unit-4-c32","front":"Cell-cycle checkpoint","back":"A control point where stop-and-go signals regulate progression through the cell cycle."},{"id":"apbio-unit-4-c33","front":"Cyclin-dependent kinase (CDK)","back":"A protein kinase activated by binding a cyclin; cyclin-CDK complexes regulate cell-cycle transitions."},{"id":"apbio-unit-4-c34","front":"Cancer","back":"Uncontrolled cell division caused by failures in normal cell-cycle regulation."},{"id":"apbio-unit-4-c35","front":"Signal amplification","back":"Multiplication of a cellular signal as one activated component activates many downstream molecules."},{"id":"apbio-unit-4-c36","front":"Quorum sensing","back":"Cell-to-cell signaling that allows microorganisms to coordinate gene expression according to population density."},{"id":"apbio-unit-4-c37","front":"Caspase","back":"A protease that participates in the signaling cascade and controlled cellular dismantling of apoptosis."},{"id":"apbio-unit-4-c38","front":"Proto-oncogene","back":"A normal gene that promotes cell growth or division and can become an oncogene when mutated or overexpressed."},{"id":"apbio-unit-4-c39","front":"Tumor-suppressor gene","back":"A gene whose product restrains cell division, repairs DNA, or promotes apoptosis; loss of function can contribute to cancer."}],"questions":[],"feynmanPrompts":[{"id":"apbio-unit-4-f1","prompt":"Signal transduction pathways"},{"id":"apbio-unit-4-f2","prompt":"Feedback regulation"},{"id":"apbio-unit-4-f3","prompt":"Cell-cycle control and cancer"}]},{"id":"apbio-unit-5","name":"AP Biology · Unit 5","shortName":"Unit 5: Heredity","builtIn":true,"sourceTitle":"AP Biology Course and Exam Description, Effective Fall 2025; EBSCO AP Biology Study Guide","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf","cards":[{"id":"apbio-unit-5-c1","front":"meiosis","back":"A modified type of cell division in sexually reproducing organisms consisting of two rounds of cell division but only one round of DNA replication."},{"id":"apbio-unit-5-c2","front":"fertilization","back":"The union of haploid gametes to produce a diploid zygote."},{"id":"apbio-unit-5-c3","front":"zygote","back":"The diploid cell produced by the union of haploid gametes during fertilization; a fertilized egg."},{"id":"apbio-unit-5-c4","front":"diploid cell","back":"A cell containing two sets of chromosomes (2 n), one set inherited from each parent."},{"id":"apbio-unit-5-c5","front":"somatic cell","back":"Any cell in a multicellular organism except a sperm or egg or their precursors."},{"id":"apbio-unit-5-c6","front":"sister chromatids","back":"Two copies of a duplicated chromosome attached to each other by protein at the centromere and, sometimes, along the arms."},{"id":"apbio-unit-5-c7","front":"chiasmata","back":") (kī-az ∙ -muh, kī-az ∙ -muh-tuh) The X-shaped, microscopically visible region where crossing over has occurred earlier in prophase I between homologous nonsister chromatids."},{"id":"apbio-unit-5-c8","front":"allele","back":"Any of the alternative versions of a gene that may produce distinguishable phenotypic effects."},{"id":"apbio-unit-5-c9","front":"genotype","back":"The genetic makeup, or se of alleles, of an organism."},{"id":"apbio-unit-5-c10","front":"phenotype","back":"The observable physical and physiological traits of an organism, which are determined by its genetic makeup."},{"id":"apbio-unit-5-c11","front":"law of segregation","back":"Mendel’s first law, stating that the two alleles in a pair segregate (separate from each other) into different gametes during gamete formation."},{"id":"apbio-unit-5-c12","front":"testcross","back":"Breeding an organism of unknown genotype with a homozygous recessive individual to determine the unknown genotype."},{"id":"apbio-unit-5-c13","front":"monohybrid cross","back":"A cross between two organisms that are heterozygous for the character being followed (or the self-pollination of a heterozygous plant)."},{"id":"apbio-unit-5-c14","front":"dihybrid","back":"An organism that is heterozygous with respect to two genes of interest."},{"id":"apbio-unit-5-c15","front":"Punnett square","back":"A diagram used in the study of inheritance to show the predicted genotypic results of random fertilization in genetic crosses between individuals of known genotype."},{"id":"apbio-unit-5-c16","front":"complete dominance","back":"The situation in which the phenotypes of the heterozygote and dominant homozygote are indistinguishable."},{"id":"apbio-unit-5-c17","front":"incomplete dominance","back":"The situation in s which the phenotype of heterozygotes is intermediate between the phenotypes of indie viduals homozygous for either allele."},{"id":"apbio-unit-5-c18","front":"codominance","back":"The situation in which the phenotypes of both alleles are exhibited in the heterozygote because both alleles affect the phenotype in separate, distinguishable ways."},{"id":"apbio-unit-5-c19","front":"multifactorial","back":"Referring to a phenotypic character that is influenced by multiple genes and environmental factors."},{"id":"apbio-unit-5-c20","front":"polygenic inheritance","back":"An additive effect of two or more genes on a single phenotypic character."},{"id":"apbio-unit-5-c21","front":"linked genes","back":"Genes located close enough together on a chromosome that they tend to be inherited together."},{"id":"apbio-unit-5-c22","front":"linkage map","back":"A genetic map based on the frequencies of recombination between markrk ers during crossing over of homologous chromosomes."},{"id":"apbio-unit-5-c23","front":"nondisjunction","back":"An error in meiosis or mitosis in which members of a pair of homologous chromosomes or a pair of sister chromatids fail to separate properly from each other."},{"id":"apbio-unit-5-c24","front":"genomic imprinting","back":"A phenomenon in which expression of an allele in offspring depends on whether the allele is inherited from the male or female parent."},{"id":"apbio-unit-5-c25","front":"Crossing over","back":"Exchange of corresponding DNA segments between nonsister chromatids of homologous chromosomes during prophase I."},{"id":"apbio-unit-5-c26","front":"Independent assortment","back":"The random orientation of homologous chromosome pairs at metaphase I, producing varied chromosome combinations in gametes."},{"id":"apbio-unit-5-c27","front":"Recombination frequency","back":"The percentage of recombinant offspring; it estimates the distance between linked genes up to a maximum of 50%."},{"id":"apbio-unit-5-c28","front":"Epistasis","back":"An interaction in which one gene alters or masks the phenotypic expression of another gene."},{"id":"apbio-unit-5-c29","front":"Pleiotropy","back":"The ability of one gene to affect multiple phenotypic traits."},{"id":"apbio-unit-5-c30","front":"Sex-linked trait","back":"A trait determined by a gene on a sex chromosome, most commonly the X chromosome."},{"id":"apbio-unit-5-c31","front":"Pedigree","back":"A diagram showing the inheritance of a trait through multiple generations of a family."},{"id":"apbio-unit-5-c32","front":"Environmental effect on phenotype","back":"A change in phenotype caused by environmental conditions without a change in genotype."},{"id":"apbio-unit-5-c33","front":"Genetic linkage","back":"The tendency of genes located near one another on the same chromosome to be inherited together."},{"id":"apbio-unit-5-c34","front":"Product rule","back":"For independent events, the probability that all occur equals the product of their individual probabilities."},{"id":"apbio-unit-5-c35","front":"Sum rule","back":"For mutually exclusive outcomes, the probability that one occurs equals the sum of their individual probabilities."},{"id":"apbio-unit-5-c36","front":"Map unit","back":"A unit of genetic distance corresponding to a 1% recombination frequency; it is also called a centimorgan."},{"id":"apbio-unit-5-c37","front":"Norm of reaction","back":"The range of phenotypes a genotype can produce under different environmental conditions."},{"id":"apbio-unit-5-c38","front":"Pedigree interpretation","back":"Analysis of trait patterns across generations to infer dominance, recessiveness, sex linkage, and possible genotypes."}],"questions":[],"feynmanPrompts":[{"id":"apbio-unit-5-f1","prompt":"Meiosis and genetic diversity"},{"id":"apbio-unit-5-f2","prompt":"Mendelian and non-Mendelian inheritance"}]},{"id":"apbio-unit-6","name":"AP Biology · Unit 6","shortName":"Unit 6: Gene Expression and Regulation","builtIn":true,"sourceTitle":"AP Biology Course and Exam Description, Effective Fall 2025; EBSCO AP Biology Study Guide","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf","cards":[{"id":"apbio-unit-6-c1","front":"DNA replication","back":"The process by which a DNA molecule is copied; also called DNA synthesis."},{"id":"apbio-unit-6-c2","front":"origin of replication","back":"Site where the replication of a DNA molecule begins, consisting of a specific sequence of nucleotides."},{"id":"apbio-unit-6-c3","front":"helicase","back":"An enzyme that untwists the double helix of DNA at replication forks, separating the two strands and making them available as template strands."},{"id":"apbio-unit-6-c4","front":"leading strand","back":"The new complementary DNA strand synthesized continuously along the template strand toward the replication fork in the mandatory 5 ′ S 3 ′ direction."},{"id":"apbio-unit-6-c5","front":"transcription","back":"The synthesis of RNA using a DNA template."},{"id":"apbio-unit-6-c6","front":"promoter","back":"A specific nucleotide sequence in the DNA of a gene that binds RNA polymerase, positioning it to start transcribing RNA at the appropriate place."},{"id":"apbio-unit-6-c7","front":"RNA processing","back":"Modification of RNA primary transcripts, including splicing out of introns, joining together of exons, and alteration of the 5 ′ and 3 ′ ends."},{"id":"apbio-unit-6-c8","front":"RNA splicing","back":"After synthesis of a eukaryotic primary RNA transcript, the removal of portions of the transcript (introns) that will not be included in the mRNA and the joining together of the remaining portions (exons)."},{"id":"apbio-unit-6-c9","front":"alternative RNA splicing","back":"A type of eukaryotic gene regulation at the RNA-processing level in which different mRNA molecules are produced from the same primary transcript, depending on which RNA segments are treated as exons and which as introns."},{"id":"apbio-unit-6-c10","front":"codon","back":"A three-nucleotide sequence of DNA or mRNA that specifies a particular amino acid or termination signal; the basic unit of the genetic code."},{"id":"apbio-unit-6-c11","front":"reading frame","back":"On an mRNA, the triplet grouping of ribonucleotides used by the translation machinery during polypeptide synthesis."},{"id":"apbio-unit-6-c12","front":"ribosome","back":"A complex of rRNA and oprotein molecules that functions as a site of protein synthesis in the cytoplasm; consists of a large and a small subunit."},{"id":"apbio-unit-6-c13","front":"mutation","back":"A change in the nucleotide sequence of an organism’s DNA or in the DNA or RNA of a virus."},{"id":"apbio-unit-6-c14","front":"insertion","back":"A mutation involving the addition of one or more nucleotide pairs to a gene."},{"id":"apbio-unit-6-c15","front":"deletion","back":"A deficiency in a chromosome resulting from the loss of a fragment through breakage."},{"id":"apbio-unit-6-c16","front":"operon","back":"A unit of genetic function found in bacteria and phages, consisting of a promoter, an operator, and a coordinately regulated cluster of genes whose products function in a common pathway."},{"id":"apbio-unit-6-c17","front":"operator","back":"In bacterial and phage DNA, a sequence of nucleotides near the start of an operon to which an active repressor can attach."},{"id":"apbio-unit-6-c18","front":"activator","back":"A protein that binds to DNA and stimulates gene transcription."},{"id":"apbio-unit-6-c19","front":"inducer","back":"A specific small molecule that binds to a bacterial repressor protein and changes the - repressor’s shape so that it cannot bind to an s operator, thus switching an operon on."},{"id":"apbio-unit-6-c20","front":"differential gene expression","back":"The expression of different sets of genes by cells with the same genome."},{"id":"apbio-unit-6-c21","front":"DNA technology","back":"Techniques for sequencing and manipulating DNA."},{"id":"apbio-unit-6-c22","front":"restriction enzyme","back":"An endonuclease (type of enzyme) that recognizes and cuts DNA molecules foreign to a bacterium (such as phage genomes)."},{"id":"apbio-unit-6-c23","front":"DNA polymerase","back":"An enzyme that adds DNA nucleotides to the 3' end of a growing strand and proofreads newly synthesized DNA."},{"id":"apbio-unit-6-c24","front":"Lagging strand","back":"The new DNA strand synthesized discontinuously away from the replication fork as Okazaki fragments."},{"id":"apbio-unit-6-c25","front":"Okazaki fragment","back":"A short segment of DNA synthesized on the lagging strand and later joined by DNA ligase."},{"id":"apbio-unit-6-c26","front":"Messenger RNA (mRNA)","back":"An RNA transcript that carries coding information from DNA to a ribosome."},{"id":"apbio-unit-6-c27","front":"Transfer RNA (tRNA)","back":"An adaptor RNA that pairs its anticodon with an mRNA codon and carries the corresponding amino acid."},{"id":"apbio-unit-6-c28","front":"Translation","back":"Synthesis of a polypeptide by a ribosome using the codon sequence of mRNA."},{"id":"apbio-unit-6-c29","front":"Transcription factor","back":"A regulatory protein that binds DNA and influences transcription."},{"id":"apbio-unit-6-c30","front":"Epigenetic regulation","back":"Heritable changes in gene expression caused by chromatin modifications rather than changes in DNA sequence."},{"id":"apbio-unit-6-c31","front":"Polymerase chain reaction (PCR)","back":"A technique that uses repeated temperature cycles and DNA polymerase to amplify a chosen DNA segment."},{"id":"apbio-unit-6-c32","front":"Gel electrophoresis","back":"A technique that separates nucleic acid fragments by size as they migrate through a gel in an electric field."},{"id":"apbio-unit-6-c33","front":"Topoisomerase","back":"An enzyme that relieves twisting strain ahead of the replication fork by temporarily cutting and rejoining DNA."},{"id":"apbio-unit-6-c34","front":"Single-strand binding protein","back":"A protein that stabilizes separated DNA strands and prevents them from re-forming the double helix during replication."},{"id":"apbio-unit-6-c35","front":"Primase","back":"An enzyme that synthesizes short RNA primers during DNA replication."},{"id":"apbio-unit-6-c36","front":"RNA primer","back":"A short RNA strand providing the free 3'-OH required for DNA polymerase to begin synthesis."},{"id":"apbio-unit-6-c37","front":"DNA ligase","back":"An enzyme that seals breaks in the sugar-phosphate backbone, including gaps between Okazaki fragments."},{"id":"apbio-unit-6-c38","front":"Telomerase","back":"An enzyme that extends telomeres using an internal RNA template, helping prevent loss of chromosome-end DNA."},{"id":"apbio-unit-6-c39","front":"RNA polymerase","back":"The transcription enzyme that builds RNA from a DNA template; it is not the enzyme that replicates DNA."},{"id":"apbio-unit-6-c40","front":"Lac operon","back":"An inducible bacterial gene-regulation system that permits lactose metabolism when lactose is available and glucose is scarce."},{"id":"apbio-unit-6-c41","front":"Trp operon","back":"A repressible bacterial gene-regulation system normally active until tryptophan activates its repressor."},{"id":"apbio-unit-6-c42","front":"MicroRNA (miRNA)","back":"A small RNA that associates with proteins and reduces gene expression by degrading target mRNA or inhibiting its translation."},{"id":"apbio-unit-6-c43","front":"Plasmid","back":"A small, independently replicating circular DNA molecule commonly found in bacteria and used as a cloning vector."},{"id":"apbio-unit-6-c44","front":"Bacterial transformation","back":"Uptake and incorporation of external DNA by a bacterial cell."},{"id":"apbio-unit-6-c45","front":"DNA sequencing","back":"Determination of the nucleotide order in a DNA molecule."}],"questions":[],"feynmanPrompts":[{"id":"apbio-unit-6-f1","prompt":"DNA replication"},{"id":"apbio-unit-6-f2","prompt":"Gene expression from DNA to protein"},{"id":"apbio-unit-6-f3","prompt":"Regulation of gene expression"},{"id":"apbio-unit-6-f4","prompt":"Biotechnology"}]},{"id":"apbio-unit-7","name":"AP Biology · Unit 7","shortName":"Unit 7: Natural Selection","builtIn":true,"sourceTitle":"AP Biology Course and Exam Description, Effective Fall 2025; EBSCO AP Biology Study Guide","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf","cards":[{"id":"apbio-unit-7-c1","front":"adaptation","back":"Inherited characteristic of an r organism that enhances its survival and reproduction in a specific environment."},{"id":"apbio-unit-7-c2","front":"variation","back":"Differences between members of the same species."},{"id":"apbio-unit-7-c3","front":"balancing selection","back":"Natural selection that maintains two or more phenotypic forms in a population."},{"id":"apbio-unit-7-c4","front":"Hardy-Weinberg equilibrium","back":"The state of a population in which frequencies of alleles and genotypes remain constant from generation to generation, provided that only Mendelian segregation and recombination of alleles are at work."},{"id":"apbio-unit-7-c5","front":"adaptive evolution","back":"A process in which traits that enhance survival or reproduction tend to increase in frequency over time, resulting in a better match between organisms and their environment."},{"id":"apbio-unit-7-c6","front":"directional selection","back":"Natural selection in which individuals at one end of the phenotypic range survive or reproduce more successfully than do other individuals."},{"id":"apbio-unit-7-c7","front":"mutation","back":"A change in the nucleotide sequence of an organism’s DNA or in the DNA or RNA of a virus."},{"id":"apbio-unit-7-c8","front":"allele","back":"Any of the alternative versions of a gene that may produce distinguishable phenotypic effects."},{"id":"apbio-unit-7-c9","front":"genotype","back":"The genetic makeup, or se of alleles, of an organism."},{"id":"apbio-unit-7-c10","front":"phenotype","back":"The observable physical and physiological traits of an organism, which are determined by its genetic makeup."},{"id":"apbio-unit-7-c11","front":"allopatric speciation","back":"The formation of new species in populations that are geographically isolated from one another."},{"id":"apbio-unit-7-c12","front":"speciation","back":"An evolutionary process in which one species splits into two or more species."},{"id":"apbio-unit-7-c13","front":"macroevolution","back":"Evolutionary change above the species level."},{"id":"apbio-unit-7-c14","front":"punctuated equilibria","back":"In the fossil record, long periods of apparent stasis, in which a species undergoes little or no morphological change, interrupted by relatively brief periods of sudden change."},{"id":"apbio-unit-7-c15","front":"adaptive radiation","back":"Period of evolutionary change in which groups of organisms form many new species whose adaptations allow them to fill different ecological roles in their communities."},{"id":"apbio-unit-7-c16","front":"analogy","back":"Similarity between two species that is due to convergent evolution rather than to descent from a common ancestor with the same trait."},{"id":"apbio-unit-7-c17","front":"phylogeny","back":"The evolutionary history of a species or group of related species."},{"id":"apbio-unit-7-c18","front":"phylogenetic tree","back":"A branching diagram that represents a hypothesis about the evolutionary history of a group of organisms."},{"id":"apbio-unit-7-c19","front":"clade","back":"A group of species that includes an ancestral species and all of its descendants."},{"id":"apbio-unit-7-c20","front":"monophyletic","back":"Pertaining to a group of taxa that consists of a common ancestor and all of its descendants."},{"id":"apbio-unit-7-c21","front":"sister taxa","back":"Groups of organisms that share an immediate common ancestor and hence are each other’s closest relatives."},{"id":"apbio-unit-7-c22","front":"molecular clock","back":"A method for estimating the time required for a given amount of evolutionary change, based on the observation that some regions of genomes evolve at constant rates."},{"id":"apbio-unit-7-c23","front":"Fitness","back":"An organism's relative contribution of viable, fertile offspring to the next generation."},{"id":"apbio-unit-7-c24","front":"Natural selection","back":"Differential survival and reproduction caused by heritable phenotypic variation."},{"id":"apbio-unit-7-c25","front":"Gene flow","back":"Movement of alleles between populations through migration and reproduction."},{"id":"apbio-unit-7-c26","front":"Genetic drift","back":"Random change in allele frequencies, with especially strong effects in small populations."},{"id":"apbio-unit-7-c27","front":"Founder effect","back":"Genetic drift that occurs when a new population is established by a small number of individuals."},{"id":"apbio-unit-7-c28","front":"Bottleneck effect","back":"Genetic drift following a sharp reduction in population size that leaves a nonrepresentative sample of alleles."},{"id":"apbio-unit-7-c29","front":"Stabilizing selection","back":"Selection favoring intermediate phenotypes over both extremes."},{"id":"apbio-unit-7-c30","front":"Disruptive selection","back":"Selection favoring both phenotypic extremes over intermediate phenotypes."},{"id":"apbio-unit-7-c31","front":"Sexual selection","back":"Selection arising from differences in mating success."},{"id":"apbio-unit-7-c32","front":"Reproductive isolation","back":"Biological barriers that prevent gene flow between populations."},{"id":"apbio-unit-7-c33","front":"Homologous structure","back":"A feature similar because of shared ancestry, even when its function differs among species."},{"id":"apbio-unit-7-c34","front":"Vestigial structure","back":"A reduced inherited feature that has lost most or all of its ancestral function."},{"id":"apbio-unit-7-c35","front":"Hardy-Weinberg equation","back":"For two alleles, p + q = 1 and p² + 2pq + q² = 1 describe allele and genotype frequencies in a non-evolving population."},{"id":"apbio-unit-7-c36","front":"Prezygotic barrier","back":"A reproductive barrier that prevents mating or fertilization before a zygote forms."},{"id":"apbio-unit-7-c37","front":"Postzygotic barrier","back":"A reproductive barrier that reduces hybrid viability or fertility after fertilization."},{"id":"apbio-unit-7-c38","front":"Common ancestry","back":"Shared descent inferred from homologous structures, fossils, embryology, biogeography, and molecular similarities."},{"id":"apbio-unit-7-c39","front":"Convergent evolution","back":"Independent evolution of similar traits in distantly related lineages exposed to similar selective pressures."},{"id":"apbio-unit-7-c40","front":"Allele-frequency change","back":"A change in the proportion of an allele in a population across generations; it is a measurable definition of evolution."}],"questions":[],"feynmanPrompts":[{"id":"apbio-unit-7-f1","prompt":"Natural selection and population change"},{"id":"apbio-unit-7-f2","prompt":"Hardy–Weinberg equilibrium"},{"id":"apbio-unit-7-f3","prompt":"Evidence for common ancestry"},{"id":"apbio-unit-7-f4","prompt":"Speciation and phylogeny"}]},{"id":"apbio-unit-8","name":"AP Biology · Unit 8","shortName":"Unit 8: Ecology","builtIn":true,"sourceTitle":"AP Biology Course and Exam Description, Effective Fall 2025; EBSCO AP Biology Study Guide","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf","cards":[{"id":"apbio-unit-8-c1","front":"fixed action pattern","back":"In animal behavior, a sequence of unlearned acts that is essentially unchangeable and, once initiated, usually carried to completion."},{"id":"apbio-unit-8-c2","front":"learning","back":"The modification of behavior as a result of specific experiences."},{"id":"apbio-unit-8-c3","front":"imprinting","back":"In animal behavior, the formation at a specific stage in life of a long-lasting r behavioral response to a specific individual or object."},{"id":"apbio-unit-8-c4","front":"associative learning","back":"The acquired ability to associate one environmental feature (such as a of color) with another (such as danger)."},{"id":"apbio-unit-8-c5","front":"communication","back":"In behavior, a process involving the transmission and reception of signals between organisms."},{"id":"apbio-unit-8-c6","front":"optimal foraging model","back":"The basis for analyzing behavior as a compromise between feeding costs and feeding benefits."},{"id":"apbio-unit-8-c7","front":"inclusive fitness","back":"The total effect an individual has on proliferating its genes by producing its own offspring and by providing aid that enables other close relatives to increase production of their offspring."},{"id":"apbio-unit-8-c8","front":"metapopulation","back":"A group of spatially separated populations of one species that interact through immigration and emigration."},{"id":"apbio-unit-8-c9","front":"density","back":"The number of individuals per unit area or volume."},{"id":"apbio-unit-8-c10","front":"carrying capacity","back":"The maximum population size that can be supported by the available resources, symbolized as K."},{"id":"apbio-unit-8-c11","front":"density dependent","back":"Referring to any characteristic that varies with population density."},{"id":"apbio-unit-8-c12","front":"density independent","back":"Referring to any characteristic that is not affected by population density."},{"id":"apbio-unit-8-c13","front":"community","back":"All the organisms that inhabit a particular area; an assemblage of populations of different species living close enough together for potential interaction."},{"id":"apbio-unit-8-c14","front":"ecosystem","back":"All the organisms in a given area as well as the abiotic factors with which they interact; one or more communities and the physical environment around them."},{"id":"apbio-unit-8-c15","front":"ecological niche","back":"The sum of a species’ use of the biotic and abiotic resources in its environment."},{"id":"apbio-unit-8-c16","front":"competitive exclusion","back":"The concept that when populations of two similar species compete for the same limited resources, one population will use the resources more efficiently and have a reproductive advantage that will eventually lead to the elimination of the other population."},{"id":"apbio-unit-8-c17","front":"mutualism","back":"A + / + ecological interaction that benefits individuals of both interacting species."},{"id":"apbio-unit-8-c18","front":"commensalism","back":"A + /0 ecological interaction that benefits the individuals of one species but neither harms nor helps the individuals of the other species."},{"id":"apbio-unit-8-c19","front":"primary succession","back":"A type of ecological succession that occurs in an area where there were originally no organisms present and where soil has not yet formed."},{"id":"apbio-unit-8-c20","front":"ecological succession","back":"Transition in the specie composition of a community following a disturbance; establishment of a community in an area virtually barren of life."},{"id":"apbio-unit-8-c21","front":"trophic level","back":"The position an organism occupies in a food chain."},{"id":"apbio-unit-8-c22","front":"primary production","back":"The amount of light energy converted to chemical energy (organic compounds) by the autotrophs in an ecosystem during a given time period."},{"id":"apbio-unit-8-c23","front":"species diversity","back":"The number and relative abundance of species in a biological community."},{"id":"apbio-unit-8-c24","front":"species richness","back":"The number of species in a biological community."},{"id":"apbio-unit-8-c25","front":"decomposer","back":"An organism that absorbs nutrients from nonliving organic material such as corpses, fallen plant material, and the wastes of living organisms and converts them to inorganic forms; a detritivore."},{"id":"apbio-unit-8-c26","front":"Taxis","back":"Directed movement toward or away from a stimulus."},{"id":"apbio-unit-8-c27","front":"Kinesis","back":"A nondirectional change in activity or turning rate in response to a stimulus."},{"id":"apbio-unit-8-c28","front":"Exponential growth","back":"Population growth under unlimited conditions, producing a J-shaped curve."},{"id":"apbio-unit-8-c29","front":"Logistic growth","back":"Population growth that slows near carrying capacity, producing an S-shaped curve."},{"id":"apbio-unit-8-c30","front":"Density-dependent factor","back":"A limiting factor whose effect increases with population density, such as competition or disease."},{"id":"apbio-unit-8-c31","front":"Density-independent factor","back":"A limiting factor that affects populations regardless of density, such as a severe storm."},{"id":"apbio-unit-8-c32","front":"Keystone species","back":"A species whose effect on community structure is disproportionately large relative to its abundance."},{"id":"apbio-unit-8-c33","front":"Biodiversity","back":"Variation among organisms at genetic, species, and ecosystem levels."},{"id":"apbio-unit-8-c34","front":"Ecosystem resilience","back":"The ability of an ecosystem to resist or recover from disturbance."},{"id":"apbio-unit-8-c35","front":"Ecological disruption","back":"A disturbance that changes population sizes, community interactions, or ecosystem processes."},{"id":"apbio-unit-8-c36","front":"Chi-square test","back":"A statistical test comparing observed and expected categorical counts to evaluate whether deviations are likely due to chance."},{"id":"apbio-unit-8-c37","front":"Error bar","back":"A graphical representation of variability or uncertainty around a measured value."},{"id":"apbio-unit-8-c38","front":"Gross primary productivity (GPP)","back":"The total rate at which producers capture and store chemical energy in an ecosystem."},{"id":"apbio-unit-8-c39","front":"Net primary productivity (NPP)","back":"Energy stored as producer biomass after respiration; NPP = GPP - respiration."},{"id":"apbio-unit-8-c40","front":"Trophic efficiency","back":"The percentage of production transferred from one trophic level to the next, commonly about 10%."},{"id":"apbio-unit-8-c41","front":"Secondary succession","back":"Community recovery after a disturbance that leaves soil intact."},{"id":"apbio-unit-8-c42","front":"Invasive species","back":"A nonnative species that spreads and causes ecological, economic, or human-health harm."},{"id":"apbio-unit-8-c43","front":"Standard error","back":"An estimate of how much a sample mean is expected to vary among repeated samples."},{"id":"apbio-unit-8-c44","front":"Confidence interval","back":"A range calculated from sample data that estimates a population parameter with a stated confidence level."},{"id":"apbio-unit-8-c45","front":"Statistical significance","back":"Evidence that an observed result would be unlikely under the null hypothesis at a chosen probability threshold."},{"id":"apbio-unit-8-c46","front":"Null hypothesis","back":"A testable statement predicting no real difference or association; observed deviations are attributed to chance."},{"id":"apbio-unit-8-c47","front":"Experimental control","back":"A comparison condition used to isolate the effect of the independent variable."}],"questions":[],"feynmanPrompts":[{"id":"apbio-unit-8-f1","prompt":"Population growth and regulation"},{"id":"apbio-unit-8-f2","prompt":"Community interactions"},{"id":"apbio-unit-8-f3","prompt":"Energy flow through ecosystems"},{"id":"apbio-unit-8-f4","prompt":"Biodiversity and ecosystem disruption"}]}];
